## Code Example

```javascript
// basic attestation verification sketch
function verifyAttestation(attestation, expectedHash) {
  const crypto = require('crypto');
  const actual = crypto.createHash('sha256').update(attestation).digest('hex');
  return actual === expectedHash;
}
```

